export const locales=['ru','kk','en'];
const dictionary=Object.fromEntries(lines.split('\n').map(line=>{const [key,...values]=line.split('|');return [key,values];}));
export const translator=lang=>key=>dictionary[key]?.[locales.indexOf(lang)]??key;
export const localized=(value,lang)=>Array.isArray(value)?value[locales.indexOf(lang)]:value;
